 "content": "from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    # Lines that are overwhelmingly a single color mark the retained cross-like guides.
    row_marks=[r for r,line in enumerate(grid) if max(Counter(line).values())>=w-2]
    col_marks=[c for c in range(w) if max(Counter(grid[r][c] for r in range(h)).values())>=h-2]
    # Keep all marked lines and one representative ordinary line between successive marks.
    def sample(n,marks):
        result=[]
        for i,m in enumerate(marks):
            if i==0 and m>0: result.append(0)
            result.append(m)
            if i+1<len(marks) and marks[i+1]>m+1: result.append(m+1)
        if marks and marks[-1]<n-1: result.append(n-1)
        return result
    rr=sample(h,row_marks); cc=sample(w,col_marks)
    return [[grid[r][c] for c in cc] for r in rr]
